package com.slotix.reservationcore.availability;
import com.slotix.reservationcore.common.*; import com.slotix.reservationcore.company.*; import org.springframework.http.*; import org.springframework.stereotype.*; import org.springframework.transaction.annotation.*; import org.springframework.web.server.*; import java.time.*; import java.util.*;
@Service public class AvailabilityService { final AvailabilityRuleRepository rules;final ResourceBlockRepository blocks;final CompanyRepository companies;final TenantAccessService access;public AvailabilityService(AvailabilityRuleRepository a,ResourceBlockRepository b,CompanyRepository c,TenantAccessService d){rules=a;blocks=b;companies=c;access=d;} @Transactional(readOnly=true) public List<AvailabilitySlot> slots(UUID companyId,UUID resourceId,LocalDate date,int durationMinutes){access.requireActiveMembership(companyId);if(durationMinutes<=0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"durationMinutes must be greater than zero");Company c=companies.findById(companyId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Company not found"));ZoneId zone=ZoneId.of(c.getTimezone());short day=(short)(date.getDayOfWeek().getValue()%7);List<ResourceBlock> bs=blocks.findByCompanyIdAndResourceIdAndDeletedAtIsNullOrderByStartAtAsc(companyId,resourceId);return rules.findByCompanyIdAndResourceIdAndDeletedAtIsNullOrderByWeekdayAscStartLocalTimeAsc(companyId,resourceId).stream().filter(r->r.getWeekday()==day&&(r.getEffectiveFrom()==null||!date.isBefore(r.getEffectiveFrom()))&&(r.getEffectiveTo()==null||!date.isAfter(r.getEffectiveTo()))).flatMap(r->{List<AvailabilitySlot> out=new ArrayList<>();for(LocalTime t=r.getStartLocalTime();!t.plusMinutes(durationMinutes).isAfter(r.getEndLocalTime());t=t.plusMinutes(durationMinutes)){Instant s=ZonedDateTime.of(date,t,zone).toInstant(),e=s.plusSeconds(durationMinutes*60L);if(bs.stream().noneMatch(b->s.isBefore(b.getEndAt())&&e.isAfter(b.getStartAt())))out.add(new AvailabilitySlot(s,e));}return out.stream();}).toList();}}
